/* RecompWatch admin — edit in the browser, then download the new data/data.js */
const D=JSON.parse(JSON.stringify(window.RW_DATA)),$=(s,r=document)=>r.querySelector(s);let cur=null;D.paid=D.paid||[];
const split=t=>t.split('\n').map(s=>s.trim()).filter(Boolean),lines=a=>(a||[]).join('\n');
const pg=u=>{try{return /(^|\.)paygate\.to$/i.test(new URL(u).hostname)}catch{return false}};
const esc=s=>String(s??'').replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
const b64=u=>btoa(String.fromCharCode(...u));
async function enc(url,code){const s=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),m=await crypto.subtle.importKey('raw',new TextEncoder().encode(code),'PBKDF2',false,['deriveKey']),k=await crypto.subtle.deriveKey({name:'PBKDF2',salt:s,iterations:200000,hash:'SHA-256'},m,{name:'AES-GCM',length:256},false,['encrypt']);
 return{s:b64(s),i:b64(iv),c:b64(new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},k,new TextEncoder().encode(url))))}}
const F=[['id','ID (used in the page URL)','t'],['name','Name','t'],['by','Owner / credit (e.g. user/repo)','t'],['stage','Stage','s'],['score','Progress % (0-100)','n'],['url','Repository / website URL','t'],['summary','Summary','a'],['tags','Tags (comma separated)','c'],['works','What works (one per line)','l'],['blocks',"What's blocking (one per line)",'l'],['metrics','Detail metrics (one per line: Name | percent | label)','m'],['videos','Videos / proof links (one per line: URL  or  Label | URL)','v'],['updates','Updates (one per line: YYYY-MM-DD | text)','u'],['links','Extra links (one per line: Label | URL)','k'],['download','Download URL (blank = repo /releases)','t'],['donate','Donation URL (paygate.to link only)','t'],['avatar','Avatar image path or URL','t'],['stars','Stars','t'],['forks','Forks','t'],['issues','Open issues','t'],['commits','Activity','t'],['pushed','Last push (e.g. 3h ago)','t'],['reviewed','Reviewed (date)','t'],['archived','Archived (no longer ranked)','b'],['archivedNote','Archive note','t']];
const pairs=(a,f)=>(a||[]).map(f).join('\n');
const val=(p,k,t)=>t==='c'?p[k].join(', '):t==='l'?lines(p[k]):t==='u'?pairs(p[k],u=>u.date+' | '+u.text):t==='k'?pairs(p[k],u=>u.label+' | '+u.url):t==='m'?pairs(p[k],m=>[m.name,m.pct,m.label].join(' | ')):t==='v'?pairs(p[k],v=>typeof v==='string'?v:(v.label?v.label+' | ':'')+v.url):p[k]??'';
const sp=s=>{const i=s.indexOf('|');return i<0?[s.trim(),'']:[s.slice(0,i).trim(),s.slice(i+1).trim()]};
function parse(t,v){if(t==='n')return parseFloat(v)||0;if(t==='c')return v.split(',').map(s=>s.trim()).filter(Boolean);if(t==='l')return split(v);
 if(t==='u')return split(v).map(s=>{const[a,b]=sp(s);return{date:a,text:b}});if(t==='k')return split(v).map(s=>{const[a,b]=sp(s);return{label:a,url:b}});
 if(t==='m')return split(v).map(s=>{const[a,b,c]=s.split('|').map(x=>x.trim());return{name:a,pct:parseFloat(b)||0,label:c||''}});
 if(t==='v')return split(v).map(s=>{const[a,b]=sp(s);return /^https?:/i.test(a)||!b?{url:s.trim(),label:''}:{label:a,url:b}});return v}
function list(){$('#pl').innerHTML=D.projects.map((p,i)=>`<div class="pi ${i===cur?'on':''}" data-i="${i}"><span>${esc(p.name)}</span><span>${p.score}%</span></div>`).join('');document.querySelectorAll('.pi').forEach(e=>e.onclick=()=>{cur=+e.dataset.i;list();form()})}
function form(){const p=D.projects[cur];if(!p){$('#fm').innerHTML='<div class="empty">Pick a project or add a new one.</div>';return}
 $('#fm').innerHTML=`<div class="box"><h3>Edit: ${esc(p.name)}</h3><div class="f">${F.map(([k,l,t])=>t==='b'?`<label><span><input type="checkbox" data-k="${k}" ${p[k]?'checked':''}> ${l}</span></label>`:t==='s'?`<label>${l}<select data-k="${k}">${[['race','Race (ranked)'],['private','Private build (not ranked)'],['watch','Watchlist']].map(o=>`<option value="${o[0]}" ${p[k]===o[0]?'selected':''}>${o[1]}</option>`).join('')}</select></label>`:`<label>${l}${['a','l','u','k','m','v'].includes(t)?`<textarea data-k="${k}" data-t="${t}">${esc(val(p,k,t))}</textarea>`:`<input data-k="${k}" data-t="${t}" value="${esc(val(p,k,t))}" ${t==='n'?'type="number" step="0.1" min="0" max="100"':''}>`}</label>`).join('')}</div><p style="margin-top:14px"><button class="btn" id="del">🗑 Delete project</button></p></div>`;
 document.querySelectorAll('#fm [data-k]').forEach(e=>e.oninput=e.onchange=()=>{p[e.dataset.k]=e.type==='checkbox'?e.checked:parse(e.dataset.t,e.value);list()});
 $('#del').onclick=()=>{if(confirm('Delete '+p.name+'?')){D.projects.splice(cur,1);cur=null;list();form()}}}
function paidUI(){$('#paid').innerHTML=D.paid.map((f,i)=>`<div class="box" style="background:var(--bg2)"><div class="f">${[['title','Title'],['desc','Description'],['price','Price label (e.g. $9)'],['paygate','PayGate payment link (paygate.to only)'],['_url','Secret file link (Mega / Drive / etc.) — leave blank to keep the saved one'],['_code','Unlock code you give to buyers (set it to (re)lock the file link)']].map(([k,l])=>`<label>${l}<input data-i="${i}" data-k="${k}" value="${esc(f[k]||'')}"></label>`).join('')}<div class="by">${f.enc?'🔒 A locked file link is saved.':'⚠ No file link saved yet.'}</div><p><button class="btn sm" data-rm="${i}">Remove</button></p></div></div>`).join('');
 document.querySelectorAll('#paid input').forEach(e=>e.oninput=()=>D.paid[+e.dataset.i][e.dataset.k]=e.value);document.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{D.paid.splice(+b.dataset.rm,1);paidUI()})}
$('#addpaid').onclick=()=>{D.paid.push({id:'file-'+Date.now()%1e6,title:'New file',desc:'',price:'',paygate:''});paidUI()};
$('#add').onclick=()=>{D.projects.unshift({id:'new-project-'+Date.now()%1e5,stage:'race',name:'New project',by:'',url:'',avatar:'',tags:[],summary:'',score:0,works:[],blocks:[],metrics:[],stars:'',forks:'',issues:'',commits:'',pushed:'',reviewed:new Date().toISOString().slice(0,10),archived:false,archivedNote:'',download:'',donate:'',videos:[],updates:[],links:[]});cur=0;list();form()};
$('#sd').value=D.site.release.slice(0,16);$('#don').value=D.site.donateUrl||'';$('#ctc').value=D.site.contact||'';$('#iss').value=D.site.issues||'';$('#hist').value=(D.site.history||[]).map(h=>h.date+' | '+h.score).join('\n');
$('#dl').onclick=async()=>{D.site.release=new Date($('#sd').value).toISOString();D.site.donateUrl=$('#don').value.trim();D.site.contact=$('#ctc').value.trim();D.site.issues=$('#iss').value.trim();
 D.site.history=split($('#hist').value).map(s=>{const[a,b]=sp(s);return{date:a,score:parseFloat(b)||0}});
 const bad=[['Website donation',D.site.donateUrl],...D.projects.map(p=>['Project '+p.name,p.donate]),...D.paid.map(f=>['Paid file '+f.title,f.paygate])].filter(x=>x[1]&&!pg(x[1]));
 if(bad.length)return alert('Only paygate.to links are allowed. Fix these:\n\n'+bad.map(x=>x[0]+': '+x[1]).join('\n'));
 for(const f of D.paid){if(f._url){if(!f._code)return alert('Set an unlock code for "'+f.title+'".');if(!/^https?:\/\//.test(f._url))return alert('File link for "'+f.title+'" must start with https://');f.enc=await enc(f._url,f._code)}
  if(!f.enc)return alert('"'+f.title+'" has no file link yet.');delete f._url;delete f._code}
 paidUI();const js='/* RecompWatch data — edit via the admin page (or by hand). Payments: paygate.to links only. */\nwindow.RW_DATA = '+JSON.stringify(D,null,1)+';\n';
 const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([js],{type:'text/javascript'}));a.download='data.js';a.click()};
list();form();paidUI();
